<?php
if ( ! defined( 'ABSPATH' ) ) exit;

/** Read-only, profile-aware staff handover. No setup action runs on page load. */
class MBS_Operator_Guide {
    public function init() { add_action( 'admin_menu', array( $this, 'menu' ), 30 ); }
    public function menu() { add_submenu_page( 'mathlin-booking', 'Staff guide', 'Staff guide', 'mbs_manage_bookings', 'mathlin-guide', array( $this, 'render' ) ); }
    public static function profile() {
        return array( 'campsite' => MBS_Campsite_Policy::enabled(), 'payments' => MBS_Payment_Features::enabled( 'payments' ), 'multi_area' => MBS_Space_Selection::enabled(), 'access' => (bool) get_option( 'mbs_access_enabled', 0 ) );
    }
    public function render() {
        if ( ! current_user_can( 'manage_options' ) && ! current_user_can( 'mbs_manage_bookings' ) ) wp_die( 'Forbidden', '', array( 'response' => 403 ) );
        $profile = self::profile();
        echo '<div class="wrap mbs-admin"><h1>MGF Venue — Staff guide</h1><p>This guide is read-only. It does not approve bookings, change settings, send messages or run a calendar sync.</p>';
        echo '<h2>Finding your way around</h2><p>Add booking is a separate sidebar option. Bookings contains recurring series, Scout nights (when enabled) and archived bookings. Calendar contains blocked dates. Requests retains its pending-change badge.</p><p>Use the section tabs above each page. Settings contains email templates, custom fields and Google Calendar sync. Help &amp; health contains this guide and the audit log; administrators also see Integration health. Existing bookmarks still work.</p>';
        echo $profile['payments'] ? '<p>Finance contains reports and any enabled additional charges or OSM integration.</p>' : '<p>Reports remains available for non-financial usage information while payment features are disabled.</p>';
        echo '<h2>Current venue profile</h2><ul><li>' . ( $profile['campsite'] ? 'Campsite: day sessions and continuous stays.' : 'Venue: room and whole-centre bookings.' ) . '</li><li>' . ( $profile['payments'] ? 'Billing enabled: inspect the issued invoice and recorded payments before chasing.' : 'Billing disabled: do not request payment or generate charges.' ) . '</li><li>' . ( $profile['multi_area'] ? 'Multiple sibling areas can share one reservation. Whole Park remains exclusive across its children.' : 'Single-space booking: parent and child dependencies still apply.' ) . '</li></ul>';
        $sections = array(
            'Daily checks' => array( 'Review pending bookings and change requests, then Integration health for overdue jobs or delivery failures.', 'Check near-term bookings, unpaid balances under their issued terms, and access readiness. Queued and transport accepted do not prove inbox delivery.', 'Read the audit before repeating a task. A cancelled or changed booking can make an older email obsolete.' ),
            'Accept or change a booking' => array( 'Open the booking and compare the exact dates, times, areas, organiser and purpose. Recheck conflicts and closures.', 'Review the final price and notification choice before approval. A preview is not a reservation or confirmation.', 'Use recurring-series controls for recurring requests. Legacy internal Scout actions report skipped conflicts; database/audit failures now roll back the complete batch. Do not retry blindly after an unclear result—refresh the current state first.' ),
            'Calendar review' => array( 'Open Google Calendar → Needs review and refresh the read-only comparison.', 'Expand “why these records appear”. Compare original references, source areas and complete dates/times. An identical title or overlap is not evidence that records are duplicates.', 'Select only proven corresponding area records. Leaving every checkbox clear preserves an unresolved match. Saving protected references does not edit the estate events; it also must not silently enable or pause sync.', 'A matched native MGF event follows the configured managed lifecycle. Estate-created references remain protected; never delete them as duplicate cleanup.' ),
            'Access and delivery' => array( 'Check the booking’s approval/payment eligibility and access-readiness state. Access delivery uses the configured day-before window.', 'Estate/HP Business bookings do not receive access codes. Do not put access codes into notes, handover files or support screenshots.', 'Check queue and provider evidence before resending. Fix an invalid address or configuration first; transport acceptance alone cannot prove receipt.' ),
            'Recovery and handover' => array( 'Record the booking/reference ID and failed action, not customer personal details or credentials. Escalate a database/read failure rather than treating an empty result as “no bookings”.', 'For a failed update, use the retained plugin rollback package and hosting recovery route. Never deactivate dependencies or restore the whole database casually: a restore can overwrite bookings created since the backup.', 'Keep administrator, booking-manager and read-only accounts separate. Remove departed staff and rotate compromised credentials. Existing pricing tiers and organisation text are not shared-account permissions.' ),
        );
        if ( ! $profile['payments'] ) $sections['Daily checks'][1] = 'Check near-term bookings and access readiness. No payment check is required while billing is disabled. Queued and transport accepted do not prove inbox delivery.';
        if ( $profile['payments'] ) $sections['Invoices, payments and extras'] = array( 'Use the outstanding balance, not the original total, when checking what is still due. Respect the issued due date and any explicitly agreed exception.', 'New itemised invoices use captured price evidence. Historical invoices must not be rebuilt from today’s rates. A PDF already emailed does not change when the plugin is updated.', 'Reusable extras are optional catalogue selections inside Additional charges, not equipment reservations. Saving a charge draft does not issue, send or collect payment. Issuing, sending, recording payment and crediting remain separate actions.', 'OSM reconciliation is separate from optional accounting CSV downloads. Review mappings and never post the same receipt twice. Retained CSV downloads are private, account-bound and expire after one hour.' );
        foreach ( $sections as $title => $steps ) { echo '<section><h2>' . esc_html( $title ) . '</h2><ol>'; foreach ( $steps as $step ) echo '<li><p>' . esc_html( $step ) . '</p></li>'; echo '</ol></section>'; }
        echo '<p><a class="button" href="' . esc_url( admin_url( 'admin.php?page=mathlin-booking' ) ) . '">Open bookings</a> <a class="button" href="' . esc_url( admin_url( 'admin.php?page=mathlin-requests' ) ) . '">Open requests</a></p></div>';
    }
}
